import{_ as e,o as t,c as i,a2 as r}from"./chunks/framework.BXzK3EA4.js";const _=JSON.parse('{"title":"安全最佳实践","description":"","frontmatter":{"title":"安全最佳实践"},"headers":[],"relativePath":"api/authentication/best-practices.md","filePath":"api/authentication/best-practices.md","lastUpdated":1795698978000}'),l={name:"api/authentication/best-practices.md"};function o(n,a,s,c,p,d){return t(),i("div",null,[...a[0]||(a[0]=[r('<p>API Key 等同于您账户的操作凭证。获得 API Key 的人可以对您账户下的资源执行关机、重启等操作。请遵循以下建议，保障账户安全。</p><h2 id="仅在服务端使用" tabindex="-1">仅在服务端使用 <a class="header-anchor" href="#仅在服务端使用" aria-label="Permalink to &quot;仅在服务端使用&quot;">​</a></h2><p>API Key 只应在您可控的服务器或运维环境中使用。</p><ul><li><strong>不要</strong>在网页前端（JavaScript）、移动应用或桌面客户端中嵌入 API Key，这些环境中的代码可以被他人查看。</li><li>如需在网页中展示资源信息，请由您自己的后端服务调用 API，再将结果返回给前端。</li></ul><h2 id="妥善保存" tabindex="-1">妥善保存 <a class="header-anchor" href="#妥善保存" aria-label="Permalink to &quot;妥善保存&quot;">​</a></h2><ul><li>使用环境变量、配置文件（并限制文件权限）或专业的密钥管理服务保存 API Key。</li><li><strong>不要</strong>将 API Key 直接写在代码中，也不要提交到 Git 等代码仓库。</li><li><strong>不要</strong>通过邮件、即时通讯工具或工单明文发送 API Key。</li></ul><h2 id="泄露后的处理" tabindex="-1">泄露后的处理 <a class="header-anchor" href="#泄露后的处理" aria-label="Permalink to &quot;泄露后的处理&quot;">​</a></h2><p>如果怀疑 API Key 已经泄露：</p><ol><li>立即提交工单，联系管理员处理。</li><li>登录控制台检查资源状态，确认是否有非预期的操作。</li></ol><h2 id="最小化分发" tabindex="-1">最小化分发 <a class="header-anchor" href="#最小化分发" aria-label="Permalink to &quot;最小化分发&quot;">​</a></h2><p>API Key 可以操作账户下的全部资源。请仅将 API Key 提供给确实需要的系统和人员。</p>',11)])])}const u=e(l,[["render",o]]);export{_ as __pageData,u as default};
